## 3.3 AgentFailureNotification

```ts
export type NotificationChannel =
  | 'AGENT_CONVERSATION'
  | 'AGENT_NOTIFICATION_INBOX'
  | 'WEB_PUSH'
  | 'DESKTOP_TOAST'
  | 'ENTERPRISE_IM'
  | 'EMAIL';

export interface AgentFailureNotification {
  readonly notificationId: string;
  readonly incidentId: string;
  readonly idempotencyKey: string;
  readonly severity: 'WARNING' | 'CRITICAL';
  readonly title: string;
  readonly summary: string;
  readonly failedAt: string;
  readonly scriptArtifactId: string;
  readonly scheduleId: string | null;
  readonly recoveryOptions: readonly [
    {
      readonly option: 'ABANDON_AND_REENTER_SUCCESS_CASE';
      readonly label: '放弃失败脚本，重新输入成功案例';
    },
    {
      readonly option: 'DESCRIBE_CHANGE_AND_REAUTHOR';
      readonly label: '描述变化，重新复刻并生成脚本';
    }
  ];
  readonly deepLink: string;
}
